INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаррада: Аҳамияти оптимизатсияи манбаъҳои об дар парвариши бадамҷан</h2>\n<p>Бадамҷан яке аз муҳимтарин маҳсулоти боғзорӣ дар Ҷумҳурии Ирон буда, рушди он ба ҳарорат, рӯшноӣ ва биҳудӯш шароити намнокноии хок ҷоҳор аст. Дар солҳои охир, бо вазъияти камбудии захираҳои об, гузариш аз обкории сатҳӣ ба системаҳои навто, ба мисли обкории қатра, ба ҳолати зарурано табдил ёфт. Системаҳои обкории қатра, хусусан ченаки ришад, бо тақсимоти равшани об ва моддаҳои хӯроки микро не танҳо истеъмолро кам мекунанд, балки стресси обрасонии растаниро дар марҳилаҳои ҳассоси гулбурй ва мевадорӣ ба ҳадди аксар мерасонанд.</p>\n<p>Корбучони бадамҷан бо обкории қатра нақшагирии дақиқро аз марҳилаи тайёрсозии хок то хариду охирин талаб мекунад. Дар ин мақола мо ҷиҳатҳои фаннӣ, ҳадди мунтамои фарағат ва вақтбарориҳо ҷоҳи обкориро дар давоми фавсҳои мухталиф меомӯзем, то ки деҳқон бо камтарин истифодаи об беҳтарин сифати меваҳоро ба даст оранд.</p>\n\n\n\n<h2>Равшанҳаҳои муносиби корбучонӣ ва равиши байни растаниҳо</h2>\n<p>Барои истифодаи дурусти ченаки ришад, роҳи корбучони бадамҷан бояд дақиқан бо хосиятҳои ченак мувофиқ бошад. Бадамҷан ба ришҳои чуқур ниёз дорад, бинобар ин корбучониро дар чангох ё ҷоҳир тавсия мекунем, то ки намнокноӣ ба чуқурии хок ворид шавад. Раҳеги дуруст калиди асосии давомнокии маҳсулот аст. Агар фарағат байни ду сатр беш аз ҳад кам бошад, рӯшноии растаниҳо кам мешавад ва бемориҳои қарзӣ паҳн мешаванд. Баръақс, фарағати зиёд боиси беҳушкории захираҳо ва гаронии хароҷотҳои нигоҳдорӣ мешавад.</p>\n<h3>Муайян кардани зичии корбучони оптималӣ</h3>\n<p>Дар киштҳои анъанавии бодомҷон, зичии нӯсорҳо ба таври чунин танзим карда мешавад, ки дар як гектар 8000 то 10000 намоиш даромад мекунад. Барои намуна, дар миқдори бобҳои бодомҷон дар гектар бояд бо эҳтиёт диққат диҳед, зеро бо зичии баланд ниёз ба оби бештар хориш мекунад. Вақти истифодаи системаи дарозии дарозӣ, одатан фавқи сатҳҳо 60 то 80 сантиметр ва фавқи ду нӯсор дар як сатҳ 40 то 50 сантиметр танзим карда мешавад. Ин андозаҳо имкон медиҳад, ки пӯшиши оборишӣ дар системаи дарозии дарозӣ пурра бошад ва ягон нӯсор аз гирифтани об мувофиқ маҳрум намонд. Ҳамин тавр, бобҳо бояд дар шояд ва ҳамзамон бо нӯсоркунӣ, дар сатҳи хок ҷойгир карда шаванд, то ки рӯидам аз инкишофи аввалия хуб иҷро шавад.</p>\n\n<h2>Хусусиятҳои фаннии системаи дарозии дарозӣ барои бодомҷон</h2>\n<p>Интихоби намуди системаи дарозии дарозӣ мустақиман ба сифати оборишӣ таъсир мерасонад. Барои бодомҷон, чунки ин як нӯсорест, ки ба устувории намии хок ҳисоб аст, истифодаи системаҳои дарозии дарозӣ бо партованда ё собит тавсия дода мешавад. Дар ин система, системаҳои пластикӣ, ки дорои ҷоҳои хурд мебошанд, бо ҳамроҳии системаҳои асосӣ, дар зери хок дар амиқии 2 то 3 сантиметр ҷойгир карда мешаванд. Ин амиқӣ ба решаҳои асосии нӯсор роҳи дастиро диҳад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-بادمجان-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="راهنمای جامع کاشت بادمجان با آبیاری قطره‌ای - تصویر 1"/><figcaption>усули нӯсоркунӣ киштҳои дарозии дарозӣ реҷаи оборишӣ бодомҷон</figcaption></figure>\n<ul>\n<li><strong>Намуди системаи дарозӣ:</strong> Истифодаи полиетилен бо қарикии стандартӣ барои устуворӣ нисбат ба фишори механикӣ ва ташаққуқи UV.</li>\n<li><strong>Шакли шояд:</strong> Ҷоҳои шакли V барои тақсимоти баробартарини об дар радиуси пӯшиш.</li>\n<li><strong>Дараи кабудшавии шиттҳои обкоронкунӣ:</strong> Дар сатҳ бо решаҳои сатҳӣ то нимдаразеи боднам.</li>\n<li><strong>Пӯшиш:</strong> Пӯшидани шиттҳо бо пластикаи сабз ё ҷола барои кам кардани буҳоршавӣ ва отлафҳои ҳашарот.</li>\n</ul>\n<p>Ҳангоми насб, ҳатман аз шитти обкоронкунии таҳкуркардашуда истифода баред, зеро боднам дар давраи рушд ҳаракат намекунад ва ниёз ба шиттҳои ҳаракаткунанда надорад. Ин шиттҳо бо фишори пасти абсорбсия ва тағҷанна обро бо оҳистӣ ва пайваст ба минтақаи решаҳо мерасонанд ва аз шустишавии моддаҳои ғизоӣ ва заҳршавии қурагон пешгирӣ мекунанд.</p>\n\n\n\n<h2>Нақшаи дақиқи обкоронкунӣ дар асоси марҳилаҳои рушд</h2>\n<p>Истифодаи оби боднам устувор нест ва бо тағйироти марҳилаҳои рушд тағйир меёбад. Нақшаи муваффақи обкоронии тағҷанна талаботи гидрологии раҳмонро дар ҳар ҳафта ҳисоб мекунад. Обкорони бештар дар марҳилаҳои аввал ба корфурӯӣи решаҳо менамояд ва камбудии об дар вақти ташкили мева боднамҳоро хурд ва сифати паст меорад.</p>\n<h3>Ҷадвали оптималии вақти обкоронии боднам</h3>\n<ol>\n<li><strong>Марҳаи хурдан то баргишавӣ (4 ҳафтаи аввал):</strong> Ҳоҷат ба намши доимӣ, аммо кам дорад. Обёрӣ ҳар ду рӯз як маротиба бо ҳаҷми кам (масалан, 400 литр дар гектар). Ҳадаф эҷоди замина барои хурдан бе шустани тоҳук аст.</li>\n<li><strong>Марҳаи гул кардан ва меваронӣ (6 то 8 ҳафтаи оянда):</strong> Оюси истифодаи об. Обёрӣ бояд иҷро карда шавад. Ҳаҷм то 600 то 800 литр дар гектар зиёд мешавад ва фосила то ҳар 2 то 3 рӯз кам мешавад. Дар ин марҳа истифодаи ҳашаракҳои ҳалкунанда бо системаи қатрагӣ (Fertigation) самараманд мешавад.</li>\n<li><strong>Марҳаи пухтани ниҳоӣ:</strong> Кам кардани тадриҷии обёрӣ барои зиёд кардани консентратсияи моддаҳои хушк дар мевоварӣ ва пешгирии шикастани мева. Фосилаи обёрӣ то 4 то 5 рӯз зиёд мешавад.</li>\n</ol>\n<p>Ҳамеша асосан ба ҳарорат ва намуди хок амал кунед. Хокҳои сазии кальцилӣ нисбатан наморо беҳтар нигоҳ медоранд ва ба обёрии камтар ниёз доранд. Барои таъмини саломатии шабакаи обёрӣ, шумо метавонед бо омӯзиши мафҳумҳои асосӣ дар <a href=\'https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A2%D8%A8%D8%AF%D9%87%DB%8C-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%D8%A2%D8%A8%DB%8C%D8%A7%D8%B1%DB%8C/\' target=\'_blank\'>Ҳаҷми обрасонии шинаки системаи обёрӣ</a>Даромаи равонашавӣ ва суръати ғизои даразрӯза ғояно идорагандӣ кунед.</p>\n\n<h2>Нуқтаҳои амалии муҳим барои сохтагони заминдорӣ</h2>\n<p>Уҷрои дурусти киштҳои тӯртӯрка бо системаи қатрагӣ танҳо ба насби банд ба наздик меомад. Идораии муштанокуи хока, ҳақоқӣ, ва дороздҳон, 50% аз муваффақияти маҳсулоти шуморо муайян мекунад. Ба истифодаи дарозеки моҳҳо ба ороишҳои бандҳо иқомат кунед, зеро моддаҳои зарарнок меоянд, ки сӯроҳҳои бандҳоро вобастаанд. Беҳтар аст, ки ба иҷрои зиллодгӣ ё пӯлоди истифода баред, то ҷалби ҳақоқиро то 6 моҳ идора кунед.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-بادمجان-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="راهنمای جامع کاشت بادمجان با آبیاری قطره‌ای - تصویر 2"/><figcaption>Usulhoi kishtnomii qatrigii dorohomii turtorka</figcaption></figure>\n<ul>\n<li><strong>Ҷавоб ба таҳмилоти абӣ:</strong> Нишони хушкӣ, заргирдани баргҳо хурд аст. Агар банд пошед, фосилаи ободони кӯтоҳ кунед.</li>\n<li><strong>Ҷавоб ба таҳмилоти абӣ:</strong> Нишони зиёд будани об, чабукшавии баргҳо ва заргирдани хурд аст. Агар намистӣ аз замин хориҷ шавад, даромаи равонашавиро кам кунед.</li>\n<li><strong>Реакция ба рӯшнӣ:</strong> Бодирин ба ҳарорати баланд аз 30 дараҷа ҳассос аст. Дар ошёнаи тобистон, барои кам кардани бугишдани намии хок аз сиворҳои нимшаффоф дар рӯйи ришии рӯйхӯрӣ истифода барад.</li>\n</ul>\n<p>Инчунин дар интихоби бӯд, ба муқовимати он ба бемориҳои фитоптпора ва вируси сари заҳролӣ диққат диҳед. Дар корҳои якхел, истифодаи бӯдҳои иловагардӣ ниёз ба баҳорӣ кунро ба ҳадди ақал мерасонад ва рӯҳои рӯи қавитар барои гирифтан моддаҳои ғизоӣ месозад.</p>\n\n\n\n<h2>Саволҳои маъмулӣ (FAQ)</h2>\n<h3>Оё системаи обёрӣ ба рӯй рӯи бодирин ба сӯзидани рӯи рӯи мерасонад?</h3>\n<p>Не, агар расми тақвимии дақиқ дошта бошед. Системаи рӯйрӯй бо эҷоди номи муқовимат, аз номи номи оғозӣ пешгирӣ мекунад. Ин система дар воқеъ барои немотҳои монанд ба бодирин, ки ба устувории номи ҳассосанд, беҳтарин интихоб аст.</p>\n<h3>Беҳтарин вақти насби ришии рӯйхӯрӣ кай аст?</h3>\n<p>Ришии рӯйхӯрӣ бояд ҳамзамон бо тақсимоти хок ва тайёркунии кӯҳи корӣ, дар тақсимоти бӯдпашӣ насб шавад. Азбаски бодирин немотест, ки аз рӯи рӯи намоён намебошад, мақоли ришии рӯйхӯрӣ бояд пурра солим ва бе такрор бошад.</p>\n<h3>Оё имкони пардохти моддиҳо бо системаи оромии тамчилӣ вуҷуд дорад?</h3>\n<p>Бале, ва ин кор барори карда мешавад. Системаҳои фертигасия, ки бо ороии тамчилӣ истифода мешаванд, самаранокии ҳосили моддаҳои моддии оҳистаро аз 30% дар ороии хокӣ то зиёда аз 80% мерасонанд. Шумо метавонед нишонгиҳанҳои нитратии калсий ва фосфорро ба таркиби оби шустан ба шобкаи ороӣ ворид кунед.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-بادمجان-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="راهنمای جامع کاشت بادمجان با آبیاری قطره‌ای - تصویر 3"/><figcaption>planting methods drip crop irrigation schedule бодирён</figcaption></figure>\n<h3>Фосилаи шиназот аз бодирён чӣ қадар бояд бошад?</h3>\n<p>Шиназот бояд дар чуқурии 2 то 3 сантиметр ва дар радиуси 10 то 15 сантиметр аз решаи бодирён ҷойгир бошад. Ин фосила имкон медиҳад, ки рӯҳат пур шавад ва мустақиман ба сарвари ва баргҳо нарасад.</p>\n\n<h2>Хулоса ва суханҳои ниҳоӣ</h2>\n<p>Кашти бодирён бо <a href=\'https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A2%D8%A8%D8%AF%D9%87%DB%8C-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%D8%A2%D8%A8%DB%8C%D8%A7%D8%B1%DB%8C/\' target=\'_blank\'>Ороии тамчилӣ</a> Чу яке усули оқилона барои истифодаи сармояи маҳдуди об, он метавонад ҳосилро ба таври назаррас меъморонад. Муваффақияти ин намudi кӯрҳӣ на танҳо ба сифати лентаҳои Тип вобаста аст, балки ба тарҳрезии дурустии масофаи бода, назорати дақиқи барномаи замонави бодаву ғаллодон ва истифодаи бодаҳои муқовиматманд аз ҷиҳати муҳити зист имкон медиҳад. Бо татбиқи шояндаи ин усулҳо, шумо метавонед бо кам кардани хароҷотҳои зараррасон, кам кардани нобудшавии оби заминаву зиёд кардани ҳиссаи бодаҳои бузург, ба фоидаи дурахмон дар соҳаи кишоварии худ ноил шавед. Фаромӯш накунед, ки ҳар як нишвориягӣ хусусияти ягона дорад ва гӯша, бе парвариши оқилона, ҳосили сифати паст медиҳад.</p>\n<p><strong>Мавзӯҳои алоқаманд:</strong> <a href="https://navar-abyari.ir/%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be-%d8%ab%d8%a7%d8%a8%d8%aa-fixed-spray-tape/">Лентаи Типи собит Fixed Spray Tape</a>, <a href="https://navar-abyari.ir/%D8%A2%D8%A8%DB%8C%D8%A7%D8%B1%DB%8C-%DA%AF%D8%B1%D9%87%D8%A7%DB%8C-%DB%8C%D8%A7-%D8%AE%D9%86%D8%AF%D9%82/">D8A2D8A8DB8CD8A7D8B1DB8C DAAFD8B1D987D8A7DB8C DB8CD8A7 D8AED986D8AFD982</a>, <a href="https://navar-abyari.ir/lettuce-yield-per-hectare-factors-increase/">lettuce yield per hectare factors increase</a></p>','Комплексӣ дастурамбар барои парҳези бӯднок бо системаи обдорӣ ноқтагӣ','Дар ин мақола мо усули беҳтарини партодани баклажон бо истифода аз навари оборӣро баррасӣ мекунем. Бо ҷадвали вақтбарорӣ барои оборӣ дар мавсимҳои гуногун, шуморо бо асоси зиёд бакардиши об ва зиёд кардани андозаи ин маҳсули боғчавӣ шинос мекунем.','publish','closed','closed','kompleksi-dasturambar-baroy-parhez-budnok-obdori-nuqtayi',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
