INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Як дастурамбар комил ва амалӣ барои кишоварон барои парҳези бӯднок бо истифода аз технологияи муосири обдории ноқтагӣ. Ин маълумотро дастгирӣ мекунед то ҳосили баланд ва саноҳатии бӯднокро таъмин кунед.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
