INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаррарот: Аҳамияти ҷойгиршавии дурусти хатҳои оғози дар саҳни ғизоӣ</h2>\n<p>Саҳни ғизоӣ (ғизоҳои ҳайвоноти маҳаллӣ) бо сабаби ҳассосии баланд ба шиддати обӣ ва ниёз ба рутубати ягона дар атрофи системаи решаҳо, яке аз ҷиддитарин чегонҳо барои системаҳои оғози қатрагӣ мебошад. Бисёр деҳқонони фикр мекунанд, ки танҳо насби <a href="https://navar-abyari.ir/components-drip-irrigation-tape-dripper/">қатрагузор</a> кифоя аст, аммо воқеат ин аст, ки <strong>ма фосилаи физикии нӯри қатрагузор аз маркази саф</strong> ва инчунин <strong>масофа байни нури мувозӣ</strong>мафосилаи охирини сифати маҳсулро муайян мекунад. Агар масофаи нӯри қатрагузор аз меҳвари саф муносиб набошад, ё дар минтақаи кор оғозӣ хушкӣ мепадарад, ё дар натиҷаи ҷамъшавии рутубат бо заҳмӣ пур мешавад.</p>\n<h3>Таъсири масофа ба минтакаи фаъолии решаҳо</h3>\n<p>Системаи чархакунии қатъӣ тавассути созиши намоишбахш (Wetting Fringe) кор мекунад. Дар парвариши марз, ки решаҳо дар чуқурии 20 то 30 см фаъолият мекунанд, ҳадафи асосӣ ин аст, ки ин намоишбахши намнокӣ дақиқан зер ё каме пеш аз гӯлдонкашии барқарор карда шавад, то ҷабби осонтарин элементҳои озуавӣ, ба монанди потасий ва нитроген амалӣ гардад. Масафаҳои зиёд боиси инъикоси зиёди энергия барои бароиши об мегарданд ва дар шароити гармӣ бар қароргирифта, дар ҳолати стресс меандозанд.</p>\n\n\n\n<h2>Стандартҳои тавсияшудаи масофаи чархакунии қатъӣ</h2>\n<p>Муайян кардани масофаи дақиқи чархакунии қатъӣ ба ду тағйирёбандаи асосӣ вобаста аст: намуди ҷуръат/намунаи марз ва тақсимоти сатҳҳо (Row Layout). Дар зери ин, стандартҳои техникии ва иҷроразӣ, ки аз рӯи таҳқиқотҳои агронимикии таҳия шудаанд,ро мӯҳим дорем.</p>\n<h3>Масофаи намоишбахш аз маркази сатҳ (Lateral Spacing)</h3>\n<p>Барои аксари нигарҳонҳои савдоии марз бо баландии пушт кӯрҳазар камтар аз 1.5 метр, тавсия мешавад, ки масофаи чархакунии қатъӣ аз маркази сатҳ (ҷое ки ҷуръат гузохта шудааст) байни <strong>10 то 15 сантиметр</strong> бошад. Ин масофа боиси он мегардад, ки намоишбахши намнокӣ бо канори берунии гӯлдонкашии ё хатчакашии чорам мутаносиб шавад. Агар ҷои гузоштани лӯлаҳо бо қувваи механизмҳо маҳдуд бошад, ҳадди ақалли масофаи 10 сантиметр бояд риоя шавад, то системаи решаҳо дар оғоз озод бошад. Аммо дар нигарҳонҳои кӯрҳазар, ки пардаи баргҳо паҳнтар аст, масофаи 15 то 20 сантиметр метавонад қонибтар бошад, дар ҳолате ки суръати обӣ кардани қутуфӣ кам карда шавад, то намнокӣ чуқуртар даргезишад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-مرزه-استانداردهای-توصیهشده-تصویر-شاخص.webp" alt="فاصله نوار تیپ در کشت مرزه: استانداردهای توصیه‌شده - تصویر 1"/><figcaption>фавоси ранги нима (дип) дар тарҳи паҳлӯ ба паҳлӯ барои мерз</figcaption></figure>\n<h3>Фавоси байни лентҳои баҳорамони дар риштаҳои дупаҳлӯ</h3>\n<p>Бисёр заминаҳои мерз барои зиёд кардани зичӣ аз ҷойгиршавии риштаҳои дупаҳлӯ истифода мебаранд. Дар ин ҳолат, ду лентаи дипломӣ бо якдигар параллел бо фавоси муайян оварда мешаванд. Фавоси байни ин ду лента бояд камтар аз <strong>40 сантимертр</strong> набошад, то ғарқшавии минтақаҳои намнок ва баланд шудани шадиди намнокӣи нисбӣ дар миёнаи риштаро пешгирӣ кунанд. Ғарқшавии намнок муҳити мувофиқро барои рушди қаричҳои хокӣ ва зингарӣ тавлид мекунад. Бинобар ин, нигоҳ доштани фазои ҳаводор байни лентҳо як стандарт олдин дар муҳандисии ободории сабзавот аст.</p>\n\n<h2>Таҳлили фаннӣ: Алоқаи фавоси бо таъсири ЭТ (Эвапотранспиратсия) ва решаҳо</h2>\n<p>Дарк кардани ин қисм барои муҳандисон ва кишинкорони касбӣ зарурӣ аст. Алоқаи мустақим байни <em>Evapotranspiration</em> (Эвапотранспиратсия) ва андозаи нақшаи намнок (Wetted Pattern) вуҷуд дорад. Фавоси лентаи дипломӣ аз решаҳо чуқурӣи ниқози обро тағйир медиҳад. Агар фавоси кӯтоҳ бошад (масалан, 5 сантимертр), об зудтар дар минтақаи сатҳӣ бухор мешавад ва чуқурӣи ниқоз кам мегардад. Аммо агар фавоси мувозунат бошад (15 сантимертр), об дар оҳастагӣ ба чуқурӣ меравад. Барои ҳисоби дақиқтар, шумо метавонед ба раҳнамои мо дар бораи <a href="https://navar-abyari.ir/miqdori-obdihiyi-novori-tipii-baroi-obeyri/">Микдори даромад об аз лентаи қатқолагуз</a> Ба ҳуҷҷатҳои мувофиқ мантобед, то ки ҳаҷми даромади мувофиқи ҳар қатқолакро дар асоси ғафсии лӯла ва фишор ҳисоб кунед.</p>\n<h3>Таъсир ба ҷабҳи моддаҳои ғизоӣ</h3>\n<p>Марзе дарахте аст, ки ба унсурҳои ризмағзӣ ниёзи баланд дорад. Лентаи қатқолагуз тавассути эҷоди минтақаи тарутобии борик, зичии фурӯ рафтани моддаҳои ғизоиро дар минтақаи мушаххас зиёд мекунад. Агар масофаи минтақа то реша хеле зиёд бошад, деҳқон маҷбур аст дараҷаи моддаҳои ғизоиро зиёд кунад, ки ба хушкшавии хок дар миёни радҳо оварда мерасонад. Бинобар ин, меъёри 10-15 см нуқтаи мувозинат байни хушкшавӣ ва камбуди об аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-مرزه-استانداردهای-توصیهشده-کاربرد-عملی.webp" alt="فاصله نوار تیپ در کشت مرزه: استانداردهای توصیه‌شده - تصویر 2"/><figcaption>فاصلеи лентаи қатқолагуз тарҳи радҳо кишт марзе</figcaption></figure>\n\n\n\n<h2>Нуктаҳои амалӣ барои иҷро дар деҳаҳои воқеӣ</h2>\n<p>Назария бе амал иҷронашаванда аст. Ҳангоми насби системаи обёрӣ додани марзе, риояи ин нуктаҳои амалӣ барои таъмини коркунии якдигар <a href="https://navar-abyari.ir/fawaid-nawwar-riyy-atip/">Лентаи қатқолагуз</a> Муҳим аст:</p>\n<ul>\n<li><strong>Ҳарифт кардан бо самти боди асосӣ:</strong> Дар минотақаҳои бодишад, ришонакукиро чунин насб кунед, ки бод аз тарафи ришонакро ба маркази қатор зарба задад, то аз хушкшудани нопардаи тарафи бодгириш пешгирӣ шуд. Агар фосилаи ришона аз меҳвари марказӣ зиёд бошад, таъсири бухоршавии бодӣ зиёд мешавад.</li>\n<li><strong>Идоракунии фишур ва ҷараён:</strong> Таъмин кунед, ки ҷараёни қаטравашкунӣ ба фосилаи физикии интихобшуда мувофиқ бошад. Агар фосила кам бошад, ҷараёни балдтара метавонад боиси равешҳои сипуқ ва бемориҳои зангинӣ гардад. Аз ҷадвалҳои техникӣ истеҳсоли корхона истифода баред.</li>\n<li><strong>Фосилаи қаторҳо (Row Spacing):</strong> Фосилаи ришонакуки ҳамеша бояд асоси пҳири кавитсия (мавод) ё фосилаи ғӯрпандӣ танзим шавад. Агар фосилаи қатор дар саҳобонашумон 50 сантиметр бошад, фосилаи ришона аз марказ 15 сантиметр кам мешавад, зеро ришонаҳои қаторҳои мукокаррӣ ҳамдигарро халал мерасонанд. Дар ин ҳолат, фосиларо то 10 сантиметр кам кунед.</li>\n</ul>\n<h3>Ёфтани камбудаи оддӣ пас аз ғӯрпандӣ</h3>\n<ol>\n<li><strong>Хушк шудани решаҳои асосӣ:</strong> Агар мушоҳида кардаед, ки баргҳои миёнаи растани зардолӣ мешаванд, эҳтимолан масофаи навори дрип то решаҳои асосӣ хеле зиёд аст. Ҳал: истифодаи навори дуюм дар масофаи бехатарӣ ё кам кардани сарфи об ва зиёд кардани фосилаи ирригатсия.</li>\n<li><strong>Фасидани асоси (пути) растани:</strong> Ин нишондиҳандаи масофаи хеле кам навори дрип то марказ (мӯътадил) аст. Об мустақиман ба асоси растани мерезад. Наворҳоро 5 то 10 сантиметр аз марказ дур бардоред.</li>\n</ol>\n\n<h2>Саволҳои маъмул (FAQ) дар бораи масофаи навори дрип</h2>\n<p><strong>1. Оё масофаи навори дрип барои ҳамаи навъҳои зардоча якхела аст?</strong><br>Не. Навъҳое, ки решаҳои сатҳии (озмо) доранд, ба масофаи камтар (10-12 сантиметр) ниёз доранд, то об tezтар ҷабб шавад. Навъҳое, ки решаҳои чуқур доранд, метавонанд аз масофаи 15-20 сантиметр истифода бароранд. Ҳамیشه бо намунабардорӣ аз решаҳо дар бағори маҳаллии худ санҷиш бароред.</p>\n<p><strong>2. Чӣ тавр беҳтарин масофаро барои бағори махсуси худ пайдо кунам?</strong><br>Як тести оддӣ иҷро кунед: баъд аз ордобарӣ, дар амиқи 15-сантиметраии хок, масофаеро, ки хок дар он таъм ва тар аст, чен кунед. Ин масофаро ба маркази safha тақсим кунед. Одатан, паҳншавии нӯри тар ба муайяни дукор аз рӯи миски горизонталӣ ду баробари масофаи афқутӣ аз реша васеъ мегардад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-مرزه-استانداردهای-توصیهشده-جزئیات-فنی.webp" alt="فاصله نوار تیپ در کشت مرزه: استانداردهای توصیه‌شده - تصویر 3"/><figcaption>масофаи лентаи қатратӣ, тарҳбандии safha, кӯдак, marze</figcaption></figure>\n<p><strong>3. Оё мехобам, ки лентаи қатратиро мустақиман дар хати корт хонам?</strong><br>Сабатандишнама мешавад. Ҷойгир кардани лента дар хати корт ба сабуқонии нӯри тар дар рӯзҳои офтобӣ бо сабаби ҷамъ шудани нури офтоб ва оби рӯи ҷарронки шаффоф ё ним-шаффоф оварда мерасонад. Ҳамеша ҳадди ақал 10-сантиметраи масофа доред.</p>\n\n<h2>Хулоса: Раҳоӣ ба самаранормаи баландтарин</h2>\n<p>Интихоб <strong>Масофаи лентаи қатратӣ дар кӯдаки marze</strong> Як қаророти муҳандисӣ-деҳқониест, ки бевосита ба коэффитсиенти камкорӣ барои об ва ҳаҷми фурӯш таъсир мерасонад. Риояи стандартҳои 10 то 15-сантиметраш барои аксари ҳолатҳо, бо назардошти самти бод ва зичии корт, беҳтарин натиҷаро меорад. Бояд дар хотир бошед, ки ордобарии қатратӣ як системаи ҳаракатист; бо тағйирёти фаслҳо ва иқлим, эҳтимолан лозим мешавад, ки ин масофаро дар оғози фасли нав санҷиш бароед. Барои фаҳмидани беҳтари қисмҳои дохилӣ ва роҳи пайваст кардани ин системаҳо, омӯзиши роҳнамои мо дар бораи <a href="https://navar-abyari.ir/components-drip-irrigation-tape-dripper/">Қисмҳои навори тамчил</a> Мумкин аст ақиқаи фаннии шуморо пуррӣ кунад. Бо татбиқи принсипҳои дурусти ҷойгирӣ на танҳо хароҷоти обро кам мекунед, балки ба партовҳои равшан ва ба бемориҳои намҳоистода мусоидат мекунед.</p>\n<p><strong>Мақолаҳои вобаста:</strong> <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%da%a9%d9%84%d8%b2%d8%a7-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Миқдори бодаи қалавух дар гектар: дастурамали мукаммал + омилҳои таъсиррасон</a></p>','Фароварии ҷоҳаи чораки дар каши бандӣ: стандартҳои тавсияшуда','Таҳқиқи мукамаи таъсири масоҳат байни наворҳои капельсозӣ бар паҳншавии намии хок ва афзоиши решаҳои сабзавотҳо. Ин дастур меъёрҳои расмӣ ва ҷузъиёти амалӣ барои ҷойгиркунии дурусти хатҳои обёрӣ дар боғзорҳои сабзавотпардозӣро пешниҳод мекунад.','publish','closed','closed','farovarai-yohaichoraki-dar-kashiband-standard-toviasishuda',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
