INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','دليل زراعة الذرة الصفراء بالري بالتنقيط والري النطاقي للمزارع العراقيين' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تعرف على أفضل ممارسات زراعة الذرة الصفراء في العراق باستخدام تقنيات الري بالتنقيط والري النطاقي، مع نصائح عملية للمزارعين لتحسين العائد والانتعش الزراعي.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
