INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Иқтидори пинҳони арзан дар оборӣи муосир</h2><p>Арзан (<em>Millet</em>) тавассути давраи кӯтоҳи зиракунии зеҳнок, ҳарорати баланд ва мувофиқат бо шароити нимхушк, барои деҳқонони тоҷикӣ, ки барои гузаштани ба инъикоби зеҳнокӣ ҷустуҷӯ мекунанд, як имконияти ҷолиб аст. Аммо мушкилии асосӣ ҳамеша дар расидан ба самаранокии устувор ва кам кардани зарари аз обории нодуруст будааст. <strong>Обории қатрагӣ барои арзан</strong> ва истифодаи <a href="https://navar-abyari.ir/obyorii-ruizamini/">обории микро-аспид</a> як услуби тағйирдиҳанда барои идоракунии дақиқи захираҳост. Дар ин мақола, роҳҳои технологияи ғашти ҳубоби арзан, вақти муайяни оборий, зичии мувофиқи ҳуҷҷатҳо ва идоракунии марҳилавӣ барои ҳуҷҷаткунии арзан дар шароити идора шудаи намнокӣро баррасӣ мекунем, то деҳқонҳо бо истифода аз додаҳои амалӣ, қарорҳои беҳтарро эҷод намоянд.</p><h2>Асосҳои илмии ҳуҷҷаткунии арзан дар ҷаноби қатораи типӣ</h2><h3>Таърих ва шартҳои муқаррамии хок</h3><p>Арз (millet) ба гурӯҳи дониҳои гармшаванда (Millet) маъмур аст ва аз ҷиҳати бӯд ва навбат, набототи мӯҳлати кӯтоҳ мебошад. Ин наботот ба ҳарорати беҳтарини парвариш (тақрибан 15 то 25 дараҷа) дар марҳилаи афзоиш ҳассос аст. Дар минтаҳоҳои коҳиши об, истифодаи нӯри чип (Tape Irrigation) ба ҷои усули анъанавии паҳн кардан, ҳарорати решаҳоро доимӣ нигоҳ медорад ва хатари бемориҳои зангориро дар решаҳо кам мекунад. <a href="https://navar-abyari.ir/blue-irrigation-tape-greenhouse-guide-0-100/">Нӯри осори сабз</a> ва чип дар парвариши арз тақсимоти якхелаи намнокро дар решаҳои сатҳии ин наботот таъмин мекунад.</p><h3>Муайян кардани зичии мувофиқи бӯд дар сатҳ</h3><p>Яке аз калидҳои муваффақӣ дар <strong>осори тамдиди арз</strong>, назорати зичии парвариш (Planting density) аст. Зичии зиёд бабаробарии манбаъҳо ва камшавии вазни дони меояд, дар ҳоле ки зичии кам ҳосилнокии умумии сатҳро поён меорад. Барои парвариш бо нӯри чип, масофаи қаторҳои осори бояд бо масофаи қаторҳои парвариш мувофиқ бошад, то намнок додани самаранок ҳама набототро фаро гирад. Шумо метавонед роҳнамоии дақиқро барои ҳисобкунии зичӣ дар <a href="https://navar-abyari.ir/millet-seed-quantity-per-hectare-guide/">Раҳнамоии миқдори бӯи арзим барои ҳектар</a> Баррасӣ кунед, то шумораи мувофиқи бӯиро дар асоси иқлим ва намуди навъ муайян созед.</p><h2>Ҷадвали тақвими оборӣ ва марҳилаи рушд қадам ба қадам</h2><p>Идоракунии обории арзим дар се марҳилаи муҳим ба нақшагирии дақиқ ниёз дорад. Рӯси арзим рӯйкарда ва паҳншуда аст ва дар шартҳои хушкӣ, наботат нисбат ба ғаллакунандаҳои дигар зудтар ба даври фишори обӣ (Water Stress) мегуряд. Бинобар ин, тартиб дар <strong>обории қатрагӣ ба арзим</strong> аз вақти паҳлос то расидан ба болиғияти физиологии, ҳатмист.</p><table style="width: 100%; border-collapse: collapse; text-align: left; margin-bottom: 1.5rem;">\n<tr>\n<th style="border: 1px solid #ddd; padding: 8px; background-color: #f2f2f2;">Марҳилаи рушд</th>\n<th style="border: 1px solid #ddd; padding: 8px; background-color: #f2f2f2;">Обнокӣ</th>\n<th style="border: 1px solid #ddd; padding: 8px; background-color: #f2f2f2;">Таъсири обёрӣ</th>\n<th style="border: 1px solid #ddd; padding: 8px; background-color: #f2f2f2;">Нақшаи тавсияшуда (барномаи нима)</th>\n</tr>\n<tr>\n<td style="border: 1px solid #ddd; padding: 8px;">Нухӯрдани ғунҷумҳо</td>\n<td style="border: 1px solid #ddd; padding: 8px;">15-20 рӯз</td>\n<td style="border: 1px solid #ddd; padding: 8px;">Кам</td>\n<td style="border: 1px solid #ddd; padding: 8px;">Обёрии сабук ва мунтазам (ҳар 2 рӯз як бор)</td>\n</tr>\n<tr>\n<td style="border: 1px solid #ddd; padding: 8px;">Рӯиши вазъиятӣ</td>\n<td style="border: 1px solid #ddd; padding: 8px;">25-35 рӯз</td>\n<td style="border: 1px solid #ddd; padding: 8px;">Миёна</td>\n<td style="border: 1px solid #ddd; padding: 8px;">Зиёд шудани шиддат ва кам шудани масофа</td>\n</tr>\n<tr>\n<td style="border: 1px solid #ddd; padding: 8px;">Данасозӣ</td>\n<td style="border: 1px solid #ddd; padding: 8px;">Охирин 14 рӯз</td>\n<td style="border: 1px solid #ddd; padding: 8px;">Истиқболи баланди қобилияти ҳаётӣ</td>\n<td style="border: 1px solid #ddd; padding: 8px;">Идоракунии дақиқ барои пур шудани дониҳо</td>\n</tr>\n</table>\n<p>Беҳтарин усул барои ҳисоб кардани миқдори дақиқи обҳои лозима дар ҳар як қаторӣ, санҷиши муносибати пипеткаҳои обҳои мавҷуда дар қаторӣ нисбат ба сатҳи истеъмолоти чави аст, то аз шустани моддаҳои ғизоӣ ё пӯшидагири пешгирӣ шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-ارزن-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="راهنمای جامع کاشت ارزن با آبیاری قطره‌ای - تصویر 1"/><figcaption>усулҳои нобуриш, қатрагӣ, ҷадвали обёрӣи ҷӯроқи арزن</figcaption></figure><h2>Роҳнамои амалӣ барои ғарос ва идоракунии намӣи хок</h2><h3>Омодагии хок ва ғароси ҳамзамон бо системаи қуттагузор (нирӣ)</h3><p>Пеш аз ғароси арзам, хокро дар ҳоҷа аз назардидаи pH ва EC (миқдори гузаронандагӣ) арзёбӣ кунед. Арзам дар ҳарорати мувофиқ (тақрибан аз 15 то 25 дараҷа) беҳтар меафрӯяд. Ғароси арзам бояд бевосита дар хатҳои қуттагузории нирӣ сурат гирад, ба тавре ки фосилаи байни ғарос ва лаблабӣ тақрибан аз 10 то 15 сантиметр бошад. Ин фосила боиси он мегардад, ки раста намӣро тавассути ришаҳои бадии нирӣ ҷабҳ кунад. Ба ҷои истифодаи системаи обёрӣкунии баҳорӣ, обёрӣкуни арзам ҳамчун намунае аз обёрӣкуни қуттагузор (микрообёрӣ), ки ба шартҳои хушкӣ хеле монанд ва мутобиқшаванда аст, ба кор меравад.</p><h3>Тарзи идоракунии тензӣ ва бемории</h3><p>Ҷидокуниҳои занбӯруғӣ ва бемории ришаҳо дар арзам бештар дар шартҳои хокҳои бо намӣ пуршуда рух медиҳанд. Бо истифода аз қуттагузории нирӣ, шумо метавонед намии хокро танҳо дар минтақаи риша (Root Zone) нигоҳ доред ва сатҳи хокро хушк нигоҳ доред. Ин кор дар кам кардани беморӣ ва баланд бардоштани сифати дон муфид аст.</p><h3>Тестҳои амалӣ: Истифода аз термометри хок</h3><p>Истифода аз сенсорҳои намӣ ё ҳатмо як термометри соддаи хокӣ дар минтақаи ришаи арзам ба шумо кӯмак мекунад, то дарёед, ки оё ришаҳо ба ҳадди критикии хушкӣ расидаанд ё не. Ин равандро дар паҳлӯи санҷиши ҳаҷми ҳосил дар ҳар метри мураббарои муайян кардани истеҳсоли ҳоҷа ҷойгир кунед.</p><p class="image-slot-container"></p><h2>Таҳлили бароридан ва сифати арзам бо қуттагузорӣ (друп)</h2><p>Яке аз асосан сабабҳоест, ки чорчинро барои оборӣи сипатанашондаи арзан кӯшиш мекунад, зиёд шудани вазни донҳо ва кам шудани хуруҷоти амалиётӣ мебошад. Арзан дар ҳолате, ки дар марҳилаи ҳосилкории донҳо фишори обӣ назиёд, ҳосилияти назаррас дорад. Барои дониши мукаммал аз истифодаи ҷадвал. <a href="https://navar-abyari.ir/millet-seed-quantity-per-hectare-guide/">Миқдори бобҳои арзан дар як гектар</a> (бо англисӣ: миқдори бобҳои милетт дар як гектар) метавонад аз назари умумӣ ба тағйирёбандаҳои рақамҳо пешгирӣ кунад. Арзанҳои зовқон дар мамоли гарм ва хушк бо чиззи зиёд ҳосилияти хуб доранд, аммо чизи зиёд кардашуда боиси рақобати байни бутабонҳо барои нур ва намӣ мекунад. Мувозинати байни ин ду, калиди ҳосилнокии давомнок аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-ارزن-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="راهنمای جامع کاشت ارزن با آبیاری قطره‌ای - تصویر 2"/><figcaption>методҳои ғиршт, оборӣи сипатанашондаи ҳосил, нақшаи оборӣ арзани</figcaption></figure><p class="image-slot-container"></p><h2>Таҳқиқи мувофиқати арзан бо иқлимҳои Эрон</h2><p>Иқлимҳои ҷануби шимолу шимолушарқии Эрон минтақаҳои муқараравӣ барои ғиршт кардани арзанд. Ин бутабон дар муқобили иқлимҳои камбаронид босор бисор мебошад. Бо идоракунии нӯри тиб, ҳатто дар минтақаҳои нимхушк, метавон арзанро бо сифати донҳои комил ҳосил кард. Ғайр аз ин, дар <a href="https://navar-abyari.ir/pakhtahosil-yeki-gektar-rahnama-kishovarzon/">Роҳнамои ҳосилияти ҳосил дар як метри мураббаъ</a> Бояд диққат дида шавад, ки арзан аз навъи ғаллеҳое мебошад, ки ба оборӣи микроаэродромӣ дар марҳилаи ҳосиикунӣ муҳакикашонанд.</p><h2>Ҷавоб ба саволҳои маъмул (FAQ)</h2><h3>1. Оё арҷин барои кишт зери нави рила мувофиқ аст?</h3><p>Бале, арҷин ба сабаби системаи решаҳои сатҳӣ ва давомии кӯтоҳ, ба нави рила ҷавоби хуб медиҳад. Решаҳо суръатан ба самти навҷо ҷозиба мешаванд ва обро бо самаранокии баланд истифода мебаранд.</p><h3>2. Кадом вақт беҳтарин вақти кӯронидани арҷин дар обории қатрагорӣ аст?</h3><p>Беҳтарин вақти кӯронидан пас аз гузаштани ҳарорати сарди бӯҳистонӣ аст (вақте ки ҳарорати хок ба 15 дараҷа расад). Арҷин ба ҳарорати паст ҳассос аст ва агар дар хоки сард кӯрон шавад, меҳварнокӣ метавонад ба ҷойи рушди ғалладона тобиш овардани беморӣ оид намояд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-ارزن-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="راهنمای جامع کاشت ارزن با آبیاری قطره‌ای - تصویر 3"/><figcaption>methodҳои кӯронидан обории қатрагорӣ расадори арҷин</figcaption></figure><h3>3. Масофаи муносиби рила дар кишти арҷин чӣ қадар аст?</h3><p>Барои кишти арҷин, масофаи байни хатҳои нави рила бояд бо масофаи зариҳои кишт мутобиқ бошад (одатан 60 то 80 см), то ки пӯшиши пурраи намӣ барои решаҳои арҷин таъмин шавад.</p><h3>4. Чӣ тавр баррасӣ кунам, ки гуногунии бӯғи арзан чӣ таъсир ба бартарӣ дорад?</h3><p>Бо истифода аз <a href="https://navar-abyari.ir/black-radish-yield-per-hectare-factors/">баррасии зерибҳо дар як гектар</a> шумо метавонед бӯҳро аз сифати баландтар интихоб кунед. Арзанҳои дани сиёҳ (Black Radish/Millet) баъзан зерибҳои гуногуни бартариро нисбат ба арзани зард доранд.</p><p class="image-slot-container"></p><h2>Хулоса ва пешниҳоди ниҳоӣ</h2><p>Користон ба айёр ба арзан, махсусан дар системаҳои обёркунӣ бо қатрагӣ ва нӯраи нип, як сармоягузорӣ дар бехатрии об ва самаранокии иқтисодӣ аст. Бо риояи ҷадвали тақвимшудаи обёркунӣ, муайян кардани зичии муносиб ва идоракунии фишори хок, шумо метавонед сифат ва миқдори арзанро дар ҳар метри мурабқа ба ҳадди аввал расонед. Ғайр аз ин корҳо, диққат ба <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d8%ac%d9%88-%d8%a8%d9%87%d8%a7%d8%b1%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">муқоисаи бартарӣ бо дигар донҳои гармӣ</a>  ва баррасии миқдори бӯҳи эсправ ва користон ба деҳқон ёрӣ мерасонад, то роҳи иқтисодии авваланро дар назар дорад. Арзан, ҳамчун маҳсулоти бисёрмарҳилагӣ, ояндаи равшанро дар чархи кӯшоникии Эрон дорад, бегоҳе ки бо обёркунии муосирамон ҳамроҳ бошад.</p>','Мутаҳаккимаи пурраи парвариши арбутӣ бо ариқҳои каппиҳо ва наҳорҳои тез','Зиракунӣ арзанро ҳамчун як наҷотҳои кӯтоҳмуддат, тавассути системаҳои оборӣ қатрагӣ ва шифтӣ метавонад ҳосилнокӣ ва сифати бӯро ба таври дидашаванда зиёд кунад. Дар ин дастурамозиши фарогиранда, мо барномаи вақт, зичии мувофиқ ва нуқтаҳои амалии идоракунии ҷазъро барои ҳосилнокии баёндар аз назар мегузаронем.','publish','closed','closed','mutahakkimii-parvarishi-arbutee-bo-ariq-ho-yi-kappi',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
