INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Дар ин мутаҳаккимаи пурра чорҳои парвариши арбутӣ бо ариқҳои каппиҳо ва наҳорҳои тезро омӯзед. Барои деҳқонони тоҷик, ки бо ҳавои гарм ва камобии об рӯбарӯанд, ин усулҳо намоиши самаранокӣ доранд.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
