INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима дар мавзӯи парвариши сабзадорон бо обёрии нӯри тиб</h2><p>Сабзадорон (Daucus carota) яки намуди растиҳоест, ки барои бозорҳои калонфурӯшӣ ва хӯроки маҳсулоти коркардашуда арзишҳои иқтисодии баланд дорад. Муваффақият дар парвариши ин маҳсул ба таври муносибат бо сифати хок, ҳарорати муҳит ва аз ҳама муҳимтараш идоракунии дурусти об алоқаманд аст. Истифодаи системаи нӯри тиб (Drip tape) яке аз зеҳнандтарин усулҳои кишоварзии муосир барои даромадноккунии сабзадорон мебошад. Ин усул на танҳо истеъмолро то 40 фоиз кам мекунад, балки бо ғизоии тадриҷӣ ва дақиқи решаҳо аз пӯсидан ва чанг задани маҳсул пешгирӣ мекунад. Дар ин раҳнамо мо раванди парвариш ва обёрии қатраи сабзадоронро аз сифр то сад баррасӣ мекунем.</p><h2>Чаро нӯри тиб беҳтарин гӯзина барои сабзадорон аст?</h2><p>Сабзадорон растиест, ки решаҳои он дар амиқии 20 то 30 сантиметрии хок фаъолият мекунанд. Истифодаи лӯлаи нӯр бо қобили 16 ё 20 миллиметр ва фосилаи депкӣ 20 сантиметрӣ, воқеан дар зери сатҳи решаҳо ҷойгир мешавад ва обро ба таври қатра-қатра расонӣ мекунад. Ин усул аз рӯйи аъмоли ғўбҳо байни сатрҳо пешгирӣ мекунад ва рутубати сатҳиро кам мекунад, ки боиси камшавии бемориҳои қаллагии қаи реша мегардад. Баръакси обёрими боронӣ, ки боиси зарби шура ва зарби рутубии тағйирёбанда мегардад, нӯри тиб мувозинати идеалӣ меъбар кардааст. Барои фаҳмиши беҳтари ҷойгиркунии дурусти система, шумо метавонед мавонод оид ба марҳилаи насби нӯри тибро хонданед, то аз насби дурусти ҷузъот боварӣ ҳосил кунед.</p><h3>Интихоби дурусти лӯлаи нӯр дар асоси шароити замин</h3><ul><li>Барои заминҳои шаърӣ ва ганҷӣ: истифодаи тибҳо бо девораҳои ғафс ва депки камтар (20 сантиметр).</li><li>Барои заминҳои шабдун: истифодаи тиб бо депки бештар (35 то 40 сантиметр) барои пешгирии хушкшавии зудии лӯла.</li><li>Тазомини раққатшавии тиб: истифодаи <a href="https://navar-abyari.ir/3-inch-cotton-pipe-guide/" target="_blank">Тӯбчаи қушлакчӣ 3 дюймӣ</a> Ҳамчун тӯбчаи асосӣ (Header) барои тақсимоти баробари фишор дар система тавсия мезавад.</li></ul><h2>Миқдори боди морқӯл ва шароити кортиб</h2><p>Яке аз таъассуротҳои асосӣ дар кариб морқӯл, хеле хурд будани бод ва вазни вазнин нисбат ба ҳаҷм мебошад. Дар боғҳои нӯри тӯбӣ, одатан аз боди пӯшида (Pelleted) истифода мешавад, то масофаи кортӣ баробар шавад. Агар аз боди табиистифода баред, лозим аст, ки онро бо рағғбарои кортиб омехта кунед. Як гектар морқӯл одатан ба 15 то 25 кг бод ниёз дорад, вобаста ба намуди анқор. Барои ошноии бештар бо ҳисобҳои дақиқтар, шумо метавонед ба мақола <a href="https://navar-abyari.ir/mikdori-tukhmi-havyz-dar-yek-ghektar-rohnamoi-purra/" target="_blank">Миқдори боди морқӯл дар як гектар</a> маъриф кунед. Масофаи сатҳҳо бо чуқурии 3 то 5 миллиметр кортӣ мешавад ва байни сатҳҳо нӯри тӯбӣ гузошта мешавад, то об дақиқан дар минтақаи решаҳо ҷараён кунад. Ин сохтори кортиб имкон медиҳад, ки реша аз фишори камобӣ наарзад ва шакли силиндрии идеалӣ дошта бошад.</p><h2>Ҷадвали вақтнокӣ ва миқдори обёрӣи қушлакчӣ барои морқӯл</h2><p>Идоракунии об дар морқӯл бояд вобаста ба марҳилаи рушд танзим шавад. Обёрии зиёд дар оғоз боиси қулоқи зардӣ мешавад ва набудани об дар охир ба пӯришии морқӯл оварда мерасонад. Ҷадвали зерин роҳнамои пурра барои идоракунии фишор ва вақт аст:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-هویج-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="راهنمای جامع کاشت هویج با آبیاری قطره‌ای - تصویر 1"/><figcaption>усулҳои кӯрон, оғӯзи алоиш бо қутта, барномаи обии сабзавот, шарбот</figcaption></figure><table border="1" cellpadding="5" cellspacing="0" style="width:100%; border-collapse: collapse; text-align:center;" data-gramm="false"><tbody><tr style="background-color:#f2f2f2;" ><th>марҳилаи рушд</th><th>вақт аз кӯрон</th><th>миқдори об дар як рӯз</th><th>шумораи марҳилаҳо</th><th>нуқтаҳои асосӣ</th></tr><tr><td>ҷавонкунии ва офаридани нав (шарбот)</td><td>рӯзҳои 1 то 15</td><td>20 то 30 литр дар метр</td><td>2 то 3</td><td>Фурӯи собити об</td></tr><tr><td>Рӯиши рӯнҳо</td><td>Рӯз 15 то 45</td><td>30 то 50 литр дар метр</td><td>2</td><td>Иловакунии тадриҷӣ</td></tr><tr><td>Баргаштан ва пуршавии реша</td><td>Рӯзҳои 45 то 60</td><td>50 то 80 литр дар ҳар метр</td><td>1 то 2</td><td>Қушғории ниёз ба об</td></tr><tr><td>Пухтани мева ва ғалоба</td><td>Рӯзҳои 60 то 75</td><td>15 то 25 литр дар ҳар метр</td><td>1</td><td>Таваққуф аз обёрӣ 1 ҳафта пеш аз ҷамъоварӣ</td></tr></tbody></table><h3>Инчунин дар бораи гардиш ва тоҳии маҳсулоти дигар</h3><p>Агар заминатон чанд навъ маҳсулот дошта бошад, метавонед аз <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D8%B4%D8%A8%D8%AF%D8%B1-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/" target="_blank">Миқдори тоҳии писта дар гектар</a> Ҳам барои муқоисаи самаранокӣ дар истифодаи об ва намнокӣ истифода баред. Гилло дар нимини аввали рушд ба гардиши нитроген ҳассос аст. Истифодаи системаи пуркунии (фидинг) дар системаи қатраҳои навори тирроӣ боиси мавҷудшудани пуркунандаи нитрогенмутаҳои маҳдуд ба минтақаи реша мегардад ва ҷабҳ беҳтар мешавад. Аз истифодаи беш аз миқдори пайдо дар рӯзҳои охир дурӣ кунед, зеро боиси сахт гардидани решаи гилло мегардад.</p><h2>Нуқтаҳои амалӣ ва пешгирии мушкилоти маъмул</h2><p>Баргузории ҳашаме бо навори тирроӣ яке аз фаъолиятҳои дақиқтарини кишоварзӣ мебошад. Агар дар ин марҳила аз хатогиҳо, ба монанди вайронии тирроӣ ё пӯшидани қатраҳо (Emitters) пешгирӣ накунед, решаи гилло аз сабаби фишори маҳаллӣ (Stress) шикаста ва барои фурӯш номуайян мегардад. Ҳамеша пеш аз борони шадид, системаро холӣ кунед. Инчунин агар замини ҳашаме дошта бошед, ба сабаби мавҷудияти кулохҳо истифодаи системаи навори тирроии шифтӣ тавсия намешавад, аммо дар хокҳои шишвор ва рангро дорӣ хеле идеалӣ аст.</p><ul><li><strong>Хатҳои сиёҳ (Black lines):</strong> Одатан аз ғирокиши бехуштар аз ҳадди оддии тухм пайдо мешавад. Дар системаи нобури ғамоиш нам, намии якхела аст ва ин мушкилӣ камтар мушоҳида мешавад.</li><li><strong>Рӯяи дугонӣ (Forked roots):</strong> Барои назорати сифати рӯяҳо аз рӯйи фосилаи нобҳои ғамоиш аз нозимҳои дугонӣ маҳорӣ ва ғирокиши дақиқ истифода баред.</li><li><strong>Заҳми сафеди рӯя (Root rot):</strong> Дар минтаҳаҳои бо намияи баланд аз нобҳои ғамоиши 30-сантиметрӣ истифода баред, то кӣ рӯя дар алоқа бо хок намидор камтар бошад.</li></ul><p>Барои шиносоӣ бо ҳисобҳо оид ба миқдори тухм барои гиёҳҳои гулдор ё дигар миқдори дон, шумо метавонед мақолаи «Миқдори тухми хушур дар гектар»-ро ҳам таҳлил кунед. Бисёри деҳқонҳо хушурро дар ҳайвати ҳатми байникиёмӣ бо шаруби (carrot) мекоранд ва барои ҳарду гиёҳ аз системаи мубтатишадани ғамоиши нобӣ (drip irrigation) истифода мебаранд. Идоракунии дурусти системаи ғамоиши нобӣ ягонаи дӯзмонӣ барои ҳайвонкӯрии шумост, ки дар солҳои оянда боқӣ хоҳад монд, агар дар охири умри системаи ғамоиши ноб, нобҳоро иваз кунед.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-هویج-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="راهنمای جامع کاشت هویج با آبیاری قطره‌ای - تصویر 2"/><figcaption>methods of planting drip crop irrigation schedule ҳушур (шаруби / carrot)</figcaption></figure><h2>Саволҳо ва ҷавобҳо (FAQ)</h2><h3>1. Оё барои системаи навози чархони барг барои сабзи чормағзин бартарафи истифода мекунем?</h3><p>Бале, ҳатман дар даромадгоҳи система як филтери дискиро бо сарҳади 80 то 120 истифода баред. Зарраҳои хурди моддаҳои олии дар об вуҷуддошуда метавонанд навозҳоро блок кунад ва дар минтақаҳо лавҳаҳои хушкшавиро ба вуҷуд орад, ки меҳвароро вайрон мекунанд.</p><h3>2. Чанд рӯз пас аз кишт навозро бояд пайваст кард?</h3><p>Дар ҳамон рӯзи кишт ё рӯзи дуюм. Сабаби ҳассосии сабзи чормағзин ба зчҳурии намии дар марҳилаи нухусткунӣ, системаи навоз бояд аз рӯзи аввал тайёр ва дар ҳолати оддӣ бошад. Ҳеҷ гоҳ имконияти мондани таркии дар хушкии мутлақро намедиҳед.</p><h3>3. Фарқи навози чархони навози оддӣ дар чист?</h3><p>Навози чархони якбора истад ва барои киштҳои мавсимии монанди сабзи чормағзин, ҷуворимох ва ҷуворимохҳои боқороҳӣ тарҳрезӣ шудааст. Ба муқоисаи навози оддӣ (Drip line) бисёрсона аст. Барои ҳар гектар сабзи чормағзин, нархи навози чархони одатан 20 то 30 фоиз арзонтар аз системаи навози доимӣ аст, ки онро аз нигоҳи муносибати дар майдони хурдтар ҷозибатар мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-هویج-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="راهنمای جامع کاشت هویج با آبیاری قطره‌ای - تصویر 3"/><figcaption>method of planting drip crop irrigation schedule saqzi chormagzino</figcaption></figure><h2>Хулоса: Ояндаи кишоварӣ бо лентаҳои намди қартоби сабз</h2><p>Комбинатсияи илми ғавсои дақиқи қартоби сабз бо технологияи лентаи намдӣ, роҳи дурусттарин барои фоидаи шумост. Дар ин усул, шумо назорати мустақимро ба сифати реша, кам кардани истеъмоли об ва пешгирӣ аз талафоти гудошӣ доред. Бо назардошти нархи баланди оби кишоварӣ, ин усул аз ҷиҳати иқтисодӣ ва муҳити зист аз беҳтарин усулҳо дар ҷаҳон аст. Ҳамеша пеш аз хариди системаи лентаи намдӣ, бо мутахассиси аз муҳандисони маҳаллӣ муроҷиа кунед ва аз филтри мувофиқ истифода баред.</p>\n<p><strong>Маводи вобаста:</strong> <a href="https://navar-abyari.ir/navori-tipi-ob-yari-plakdor/">navori tipi ob yari plakdor</a></p>','Пурраи дастури парвариши сабзи бо обкунӣи тамғагӣ ва равиши нубури TIP','Сабоғ яке аз рӯғонҳои бозорӣ аст, ки беҳтарини ҷӯзвҳои бисёрпакар аст. Гузоштани он бо системаи нафаркашӣ (тиб) самаранокии истифодаи обро баланд мебардорад. Дар ин мақола мо шароити гузоштани, барномаи нафаракишӣ ва нукти амалӣ барои даромади баландтарро шарҳ медиҳем.','publish','closed','closed','dasturi-parvarishi-sabzi-bob-okuni-tamgagi-va-ravish-tip',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
