INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Дастури мукаммал ва ихтисосӣ оид ба нигоҳубини сабзоти бо истифода аз усулҳои суғори қатқатӣ ва шитоби Tif барои кишоварон. Омӯзонед чӣ тавр самаранокиро зиёд кунед ва маҳсули баландсифат ба даст оред.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
